export function getReadingTime(article: NewsArticle): number {
  const text = article.summary + ' ' + article.content.join(' ');
  const words = text.split(/\s+/).length;
  return Math.max(1, Math.round(words / 150));
}

export function getFeaturedNews(): NewsArticle | undefined {
  return news.find((n) => n.featured) ?? news[0];
}

export function getTodayNews(): NewsArticle[] {
  return news.filter((n) => n.date === '28.09.2026' && !n.featured);
}

export function getYesterdayNews(): NewsArticle[] {
  return news.filter((n) => n.date === '14.09.2026');
}

export function getOlderNews(): NewsArticle[] {
  return news.filter((n) => n.date === '20.08.2026');
}

export function getNewsBySlug(slug: string): NewsArticle | undefined {
  return news.find((n) => n.slug === slug);
}

export function getRelatedNews(article: NewsArticle, limit = 3): NewsArticle[] {
  return news
    .filter(
      (n) =>
        n.slug !== article.slug &&
        n.tags.some((t) => article.tags.includes(t))
    )
    .slice(0, limit);
}

export function getNewsByTag(tag: string): NewsArticle[] {
  return news.filter((n) => n.tags.includes(tag as NewsTag));
}

export function formatDateGroup(date: string): string {
  const [day, month, year] = date.split('.');
  const months = [
    'января',
    'февраля',
    'марта',
    'апреля',
    'мая',
    'июня',
    'июля',
    'августа',
    'сентября',
    'октября',
    'ноября',
    'декабря',
  ];
  return `${parseInt(day)} ${months[parseInt(month) - 1]} ${year}`;
}

export function searchNews(query: string): NewsArticle[] {
  const q = query.toLowerCase().trim();
  if (!q) return [];
  return news.filter((n) => {
    const haystack = (n.title + ' ' + n.summary + ' ' + n.content.join(' ') + ' ' + n.tags.join(' ')).toLowerCase();
    return haystack.includes(q);
  });
}
